face.layout_source:
// spectral-smear.face: the panel for tap/examples/spectral/spectral-smear.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/spectral/spectral-smear.face --meta <graph>.cragmeta

face "Spectral Smear" {
  row(gap = 10) {
    box "Smear" { knob "Rise" (rise) knob.big "Decay" (decay) }
    box "Mix" { knob "Mix" (mix) }
    viz(grow = 1)
  }
}
